with recent_employees as (select * from employees where full_name like '%Sri%' and salary between 84000 and 116000), hire_month_summary as (select month(hire_date) as hire_month, sum(case when level = 'L1' then salary else 0 end) as l1_salary from recent_employees group by month(hire_date)) select hire_month, l1_salary from hire_month_summary where l1_salary >= 55 order by l1_salary desc
